import data from './prefabs.json';

export type PrefabCollider =
  | { type: 'trimesh'; v: number[]; i: number[] }
  | { type: 'hull'; v: number[] }
  | { type: 'cylinder'; radius: number; height: number }
  | { type: 'none' };

export interface PrefabInfo { size: [number, number, number]; collider: PrefabCollider }

/** Generated by scripts/assets/build.mjs from the imported models. */
export const PREFABS = data as unknown as Record<PrefabName, PrefabInfo>;
export type PrefabName =
  | 'house_a' | 'house_b' | 'house_c'
  | 'car1' | 'car2' | 'car3' | 'car4'
  | 'pine1' | 'pine2' | 'pine4' | 'pine5'
  | 'rock1' | 'rock2' | 'rock3' | 'rock4'
  | 'bush1' | 'bush2' | 'stump' | 'fence';
export const PREFAB_NAMES = Object.keys(data) as PrefabName[];
